  deserializeProp: _voiceNoteDeserializeProp,
);

int _voiceNoteEstimateSize(
  VoiceNote object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.duration.length * 3;
  bytesCount += 3 + object.filePath.length * 3;
  bytesCount += 3 + object.mood.length * 3;
  bytesCount += 3 + object.title.length * 3;
  return bytesCount;
}

void _voiceNoteSerialize(
  VoiceNote object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeString(offsets[0], object.duration);
  writer.writeString(offsets[1], object.filePath);
  writer.writeString(offsets[2], object.mood);
  writer.writeString(offsets[3], object.title);
}

VoiceNote _voiceNoteDeserialize(
  Id id,
  IsarReader reader,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  final object = VoiceNote(
    duration: reader.readStringOrNull(offsets[0]) ?? '',
    filePath: reader.readStringOrNull(offsets[1]) ?? '',
    mood: reader.readStringOrNull(offsets[2]) ?? '',
    title: reader.readStringOrNull(offsets[3]) ?? '',
  );
  return object;
}

P _voiceNoteDeserializeProp<P>(
  IsarReader reader,
  int propertyId,
  int offset,
  Map<Type, List<int>> allOffsets,
) {
  switch (propertyId) {
    case 0:
      return (reader.readStringOrNull(offset) ?? '') as P;
    case 1:
      return (reader.readStringOrNull(offset) ?? '') as P;
    case 2:
      return (reader.readStringOrNull(offset) ?? '') as P;
    case 3:
      return (reader.readStringOrNull(offset) ?? '') as P;
    default:
      throw IsarError('Unknown property with id $propertyId');
  }
}

